#!/bin/bash
# CIFAR-10 / ViT-S/4, arm=kfac. Writes to benchmarks/outputs/lot8_cifar10/vit_small/kfac/.
# Generated by benchmarks/slurm/generate_jobs.py — edit that file, not this one.
# See docs/reports/plan_lot8.md §0.11/§1.5 and benchmarks/slurm/README.md.
# Submit from the repository root:  sbatch benchmarks/slurm/train_vit_small_kfac.sh

#SBATCH --account=def-msh-ab
#SBATCH --job-name=vit_small_kfac
#SBATCH --gpus=h100_1g.10gb:1
#SBATCH --cpus-per-task=8
#SBATCH --mem=16G
#SBATCH --time=01:30:00
#SBATCH --output=benchmarks/slurm/logs/%x-%j.out

# --time: UNMEASURED extrapolation until benchmarks/slurm/calibrate_vit_small.sh has run once.
# Basis: real sacct numbers for the same model, batch size and dataset on this cluster, in
# /Users/baolgr/Documents/AtlasAnalyticsLab/experiments/default/slurm/README.md
# (20-22 min for 40 epochs of ViT-small -> ~0.55 min/epoch -> ~28 min at 50 epochs).
# Under the WCT protocol every arm takes ~the reference arm's
# wall-clock time, so all seven arms of one model share one budget. Re-tighten from real
# sacct data after the first submission.

set -euo pipefail
cd "$SLURM_SUBMIT_DIR"

module purge
module load StdEnv/2023 gcc/13.3 cuda/12.6 python/3.11.5

virtualenv --no-download "$SLURM_TMPDIR/env"
source "$SLURM_TMPDIR/env/bin/activate"
pip install --no-index --upgrade pip
pip install --no-index -r requirements-cluster.txt

export PYTHONPATH="$SLURM_SUBMIT_DIR/src"

# One WCT-budgeted arm (plan_lot8.md §0.7). WCT_BUDGET is the reference arm's measured elapsed
# time in seconds; override it at submission time once the reference job has run:
#   sbatch --export=ALL,WCT_BUDGET=6543 benchmarks/slurm/train_vit_small_kfac.sh
# Leaving it unset falls back to --budget-mode epochs, i.e. the (deliberately rigged, plan.md
# §6.3) equal-epoch comparison — usable, but not this lot's headline protocol.
WCT_BUDGET="${WCT_BUDGET:-}"
if [ -n "$WCT_BUDGET" ]; then
  BUDGET_ARGS=(--budget-mode wct --wct-budget "$WCT_BUDGET" --max-epoch-factor 3)
else
  echo "WCT_BUDGET unset — falling back to --budget-mode epochs (see this script's header)" >&2
  BUDGET_ARGS=(--budget-mode epochs)
fi

python benchmarks/cifar10_classification.py \
  --model vit_small \
  --arms kfac \
  --epochs 50 \
  "${BUDGET_ARGS[@]}" \
  --num-workers 8 \
  --no-allow-download \
  --data-root "$SLURM_SUBMIT_DIR/dataset" \
  --output-dir "$SLURM_SUBMIT_DIR/benchmarks/outputs/lot8_cifar10/vit_small/kfac"
